using DotReact.TypeGen;
using System.Text.Json;
using System.Text.Json.Serialization;
using Xunit;

namespace DotReact.TypeGen.Tests;

public sealed class TypeScriptGeneratorTests
{
    [Fact]
    public void GeneratesDeterministicContractsForSupportedTypes()
    {
        var generated = new TypeScriptGenerator().Generate([typeof(OrderDto)]);

        const string expected = """
            // <auto-generated by DotReact.TypeGen />

            export interface AddressDto {
              line1: string;
              zipCode: string | null;
            }

            export interface OrderDto {
              address: AddressDto;
              createdAt: string;
              id: string;
              isPaid: boolean;
              lines: Array<string>;
              metadata: Record<string, number>;
              optionalScores: Array<number | null> | null;
              status: OrderStatus;
              total: number;
            }

            export type OrderStatus = "Cancelled" | "Paid" | "Pending";

            """;

        Assert.Equal(expected.ReplaceLineEndings("\n"), generated);
        Assert.Equal(generated, new TypeScriptGenerator().Generate([typeof(OrderDto)]));
    }

    [Fact]
    public void RejectsUnsafeNumbersWithPropertyPath()
    {
        var exception = Assert.Throws<TypeScriptGenerationException>(
            () => new TypeScriptGenerator().Generate([typeof(UnsafeDto)]));

        Assert.Contains("System.Int64", exception.Message);
        Assert.Contains("UnsafeDto -> Value", exception.Message);
        Assert.Contains("JsonNumberHandling", exception.Message);
    }

    [Fact]
    public void GeneratesPrecisionSafeStringNumbersWhenSerializationOptsIn()
    {
        var generated = new TypeScriptGenerator().Generate([typeof(PreciseNumbersDto)]);

        Assert.Contains("amount: string;", generated);
        Assert.Contains("ids: Array<string>;", generated);
        Assert.Contains("nullableId: string | null;", generated);
        Assert.Contains("Serialized as a JSON string to preserve numeric precision", generated);

        var json = JsonSerializer.Serialize(
            new PreciseNumbersDto(12.34m, [long.MaxValue], null),
            new JsonSerializerOptions(JsonSerializerDefaults.Web));
        Assert.Contains("\"amount\":\"12.34\"", json);
        Assert.Contains($"\"ids\":[\"{long.MaxValue}\"]", json);
    }

    [Fact]
    public void GeneratesClosedGenericContractsAndNullableEnumsDeterministically()
    {
        var generated = new TypeScriptGenerator().Generate([typeof(PageDto<OrderDto>)]);

        Assert.Contains("export interface PageDtoOfOrderDto", generated);
        Assert.Contains("items: Array<OrderDto | null>;", generated);
        Assert.Contains("nextStatus: OrderStatus | null;", generated);
    }

    [Fact]
    public void RejectsCyclesWithReadablePath()
    {
        var exception = Assert.Throws<TypeScriptGenerationException>(
            () => new TypeScriptGenerator().Generate([typeof(CyclicDto)]));

        Assert.Contains("Cyclic type graph", exception.Message);
        Assert.Contains("CyclicDto -> Child", exception.Message);
    }

    [Fact]
    public void RejectsDictionariesWithNonStringKeys()
    {
        var exception = Assert.Throws<TypeScriptGenerationException>(
            () => new TypeScriptGenerator().Generate([typeof(BadDictionaryDto)]));

        Assert.Contains("must use string keys", exception.Message);
    }

    [Fact]
    public void GeneratesDiscriminatedUnionsForPolymorphicRootsAndProperties()
    {
        var generator = new TypeScriptGenerator();

        var generated = generator.Generate([typeof(MessageEnvelope)]);

        Assert.Contains("""
            export type Message =
              | (EmailMessage & { "kind": "email" })
              | (SmsMessage & { "kind": 2 });
            """.ReplaceLineEndings("\n"), generated);
        Assert.Contains("message: Message;", generated);
        Assert.Contains("messages: Array<Message>;", generated);
        Assert.Contains("export interface EmailMessage", generated);
        Assert.Contains("subject: string;", generated);
        Assert.Contains("export interface SmsMessage", generated);
        Assert.Contains("phoneNumber: string;", generated);
        Assert.Equal(generated, generator.Generate([typeof(MessageEnvelope)]));

        var rootGenerated = generator.Generate([typeof(Message)]);
        Assert.Contains("export type Message =", rootGenerated);
        Assert.Contains("EmailMessage & { \"kind\": \"email\" }", rootGenerated);

        var json = JsonSerializer.Serialize<Message>(
            new EmailMessage("message-1", "Contract generation"),
            new JsonSerializerOptions(JsonSerializerDefaults.Web));
        Assert.Contains("\"kind\":\"email\"", json);
    }

    [Fact]
    public void UsesTheDefaultSystemTextJsonDiscriminatorPropertyName()
    {
        var generated = new TypeScriptGenerator().Generate([typeof(DefaultDiscriminatorBase)]);

        Assert.Contains("DefaultDiscriminatorValue & { \"$type\": \"value\" }", generated);
    }

    [Fact]
    public void RejectsPolymorphicDerivedTypesWithoutDiscriminators()
    {
        var exception = Assert.Throws<TypeScriptGenerationException>(
            () => new TypeScriptGenerator().Generate([typeof(MissingDiscriminatorBase)]));

        Assert.Contains("MissingDiscriminatorValue", exception.Message);
        Assert.Contains("must declare a string or integer discriminator", exception.Message);
    }

    [Fact]
    public void RejectsDuplicatePolymorphicDiscriminators()
    {
        var exception = Assert.Throws<TypeScriptGenerationException>(
            () => new TypeScriptGenerator().Generate([typeof(DuplicateDiscriminatorBase)]));

        Assert.Contains("Discriminator \"duplicate\" is registered more than once", exception.Message);
        Assert.Contains(nameof(DuplicateDiscriminatorBase), exception.Message);
    }

    [Fact]
    public void SupportsDerivedTypeMetadataWithTheDefaultDiscriminatorProperty()
    {
        var generated = new TypeScriptGenerator().Generate([typeof(IncompletePolymorphicBase)]);

        Assert.Contains("IncompletePolymorphicValue & { \"$type\": \"value\" }", generated);
    }

    [Fact]
    public void RejectsDiscriminatorPropertyCollisions()
    {
        var exception = Assert.Throws<TypeScriptGenerationException>(
            () => new TypeScriptGenerator().Generate([typeof(CollidingDiscriminatorBase)]));

        Assert.Contains("Discriminator property 'kind'", exception.Message);
        Assert.Contains("collides with serialized property", exception.Message);
    }

    [Fact]
    public void RejectsPolymorphicFallbackThatCannotBeRepresentedAsAClosedUnion()
    {
        var exception = Assert.Throws<TypeScriptGenerationException>(
            () => new TypeScriptGenerator().Generate([typeof(FallbackPolymorphicBase)]));

        Assert.Contains("FallBackToBaseType", exception.Message);
        Assert.Contains("requires FailSerialization", exception.Message);
    }

    public sealed record AddressDto(string Line1, string? ZipCode);

    public sealed record OrderDto(
        Guid Id,
        DateTimeOffset CreatedAt,
        decimal Total,
        bool IsPaid,
        AddressDto Address,
        OrderStatus Status,
        List<string> Lines,
        Dictionary<string, int> Metadata,
        IEnumerable<int?>? OptionalScores);

    public enum OrderStatus
    {
        Pending,
        Paid,
        Cancelled
    }

    public sealed record UnsafeDto(long Value);

    public sealed record PreciseNumbersDto(
        [property: JsonNumberHandling(JsonNumberHandling.WriteAsString)] decimal Amount,
        [property: JsonNumberHandling(JsonNumberHandling.WriteAsString)] IReadOnlyList<long> Ids,
        [property: JsonNumberHandling(JsonNumberHandling.WriteAsString)] long? NullableId);

    public sealed record PageDto<T>(IReadOnlyList<T> Items, OrderStatus? NextStatus);

    public sealed class CyclicDto
    {
        public CyclicDto? Child { get; init; }
    }

    public sealed record BadDictionaryDto(Dictionary<int, string> Values);

    [JsonPolymorphic(TypeDiscriminatorPropertyName = "kind")]
    [JsonDerivedType(typeof(EmailMessage), "email")]
    [JsonDerivedType(typeof(SmsMessage), 2)]
    public abstract record Message(string Id);

    public sealed record EmailMessage(string Id, string Subject) : Message(Id);

    public sealed record SmsMessage(string Id, string PhoneNumber) : Message(Id);

    public sealed record MessageEnvelope(Message Message, IReadOnlyList<Message> Messages);

    [JsonPolymorphic]
    [JsonDerivedType(typeof(DefaultDiscriminatorValue), "value")]
    public abstract record DefaultDiscriminatorBase;

    public sealed record DefaultDiscriminatorValue : DefaultDiscriminatorBase;

    [JsonPolymorphic(TypeDiscriminatorPropertyName = "kind")]
    [JsonDerivedType(typeof(MissingDiscriminatorValue))]
    public abstract record MissingDiscriminatorBase;

    public sealed record MissingDiscriminatorValue : MissingDiscriminatorBase;

    [JsonPolymorphic(TypeDiscriminatorPropertyName = "kind")]
    [JsonDerivedType(typeof(DuplicateDiscriminatorOne), "duplicate")]
    [JsonDerivedType(typeof(DuplicateDiscriminatorTwo), "duplicate")]
    public abstract record DuplicateDiscriminatorBase;

    public sealed record DuplicateDiscriminatorOne : DuplicateDiscriminatorBase;

    public sealed record DuplicateDiscriminatorTwo : DuplicateDiscriminatorBase;

    [JsonDerivedType(typeof(IncompletePolymorphicValue), "value")]
    public abstract record IncompletePolymorphicBase;

    public sealed record IncompletePolymorphicValue : IncompletePolymorphicBase;

    [JsonPolymorphic(TypeDiscriminatorPropertyName = "kind")]
    [JsonDerivedType(typeof(CollidingDiscriminatorValue), "value")]
    public abstract record CollidingDiscriminatorBase;

    public sealed record CollidingDiscriminatorValue(string Kind) : CollidingDiscriminatorBase;

    [JsonPolymorphic(UnknownDerivedTypeHandling = JsonUnknownDerivedTypeHandling.FallBackToBaseType)]
    [JsonDerivedType(typeof(FallbackPolymorphicValue), "value")]
    public abstract record FallbackPolymorphicBase;

    public sealed record FallbackPolymorphicValue : FallbackPolymorphicBase;
}
